"""Build the native-size round-two asset review (not gameplay integration)."""
import pathlib,json
r=pathlib.Path(__file__).resolve().parent.parent
jobs=json.loads((r/'design/creatures/generation-jobs-round2.json').read_text())
extra=r/'design/scenes/boulder/jobs.json'
if extra.exists():jobs+=json.loads(extra.read_text())
entries=[]
for j in jobs:
 d=r/j['directory']
 if (d/'frames.json').exists():entries.append({**{k:j[k] for k in ['name','directory','category','targetWidth','targetHeight','poses']},'meta':json.loads((d/'frames.json').read_text()),'groups':j.get('animationGroups',[])})
html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Frostline · Round 2 creature art</title><style>
*{box-sizing:border-box}body{margin:0;padding:24px;font:16px/1.5 system-ui,sans-serif;background:#18333f;color:#f3ead5}header{max-width:900px}h1{font-size:30px;margin:0}a{color:#e4bd6f}p{margin:10px 0 18px}nav{display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin:14px 0}button,select{font:inherit;background:#f3ead5;color:#18333f;border:1px solid #c7a474;border-radius:5px;padding:7px;cursor:pointer}button[aria-pressed=true]{background:#e4bd6f}main{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,380px),1fr));gap:18px;margin-top:16px}article{border:1px solid #73938f;border-radius:8px;padding:16px;min-width:0}h2{margin:0;font-size:21px;text-transform:capitalize}.links,.measure{font-size:13px;color:#b6cccd}.viewer{overflow:auto;border-radius:3px;margin:12px 0;background:#edf1df}canvas,img{display:block;image-rendering:pixelated;max-width:none}.pose{min-height:24px;font-size:13px;color:#e4bd6f}.scene img{width:320px;height:200px}.scene .viewer{width:100%;background:#344b53}.scene.night img{filter:none}.hidden{display:none}#toolbar{position:sticky;top:0;background:#18333f;padding:8px 0;z-index:2;border-bottom:1px solid #73938f}footer{margin-top:28px;color:#b6cccd}
</style><header><h1>Creature art · Round 2</h1><p>Ten day/night death cards and thirteen new sprite or effects sheets. Animations are shown at their native pixel size beside the actual <strong>22-pixel skier</strong>. Select individual poses or play a cycle; 3× zoom keeps hard pixel edges.</p><p>Death cards are included in the game. This page previews source artwork independently of the current Creature Lab renderer.</p><nav><a href="design/CREATURE-ART-REQUESTS.md">Request list</a><a href="design/creatures/ROUND2.md">Asset handoff</a><a href="creature-art.html">Original artwork</a><a href="index.html?showcase=creatures">Creature Lab</a></nav></header><nav id="toolbar"><button id="native" aria-pressed="true">Native 1×</button><button id="zoom" aria-pressed="false">Pixel zoom 3×</button><button id="play" aria-pressed="true">Pause cycles</button><button id="snow" aria-pressed="false">Night backdrop</button></nav><main></main><footer>Generated with the built-in image tool. Exact prompts, original PNGs, native PNGs and frame metadata are linked from every sheet.</footer><script>
const entries=__DATA__;let zoom=1,playing=true,night=false;const views=[],atlas=new Image();atlas.src='assets/gritty-sprites.png';
function links(e){return '<div class="links"><a href="'+e.directory+'/source.png">Source</a> · <a href="'+e.directory+'/native.png">Native PNG</a> · <a href="'+e.directory+'/frames.json">Frames</a> · <a href="'+e.directory+'/prompt.txt">Prompt</a></div>'}
for(const e of entries.filter(e=>e.category==='scene'&&!e.name.endsWith('-night'))){const n=entries.find(n=>n.name===e.name+'-night'),card=document.createElement('article');card.className='scene';card.dataset.name=e.name;card.id=e.name;card.innerHTML='<h2>'+e.name.replace('death-','').replaceAll('-',' ')+'</h2><p class="measure">Death card · 320 × 200 · 64 colours</p><nav><button>Show night</button></nav><div class="viewer"><img alt="'+e.name+' daytime pixel art" src="'+e.directory+'/native.png" width="320" height="200"></div>'+links(e);let isNight=false;card.querySelector('button').onclick=()=>{if(!n)return;isNight=!isNight;card.querySelector('img').src=(isNight?n:e).directory+'/native.png';card.querySelector('img').alt=e.name+(isNight?' night':' day')+' pixel art';card.querySelector('button').textContent=isNight?'Show day':'Show night';};document.querySelector('main').append(card);}
for(const e of entries.filter(e=>e.category!=='scene')){const card=document.createElement('article');card.dataset.name=e.name;card.id=e.name;card.innerHTML='<h2>'+e.name.replaceAll('-',' ')+'</h2><p class="measure">'+e.meta.frames.length+' frames · maximum '+e.targetWidth+' × '+e.targetHeight+' native body</p>'+links(e)+'<nav><select aria-label="'+e.name+' pose or cycle"></select></nav><div class="viewer"><canvas></canvas></div><div class="pose"></div>';document.querySelector('main').append(card);const select=card.querySelector('select'),canvas=card.querySelector('canvas'),label=card.querySelector('.pose'),im=new Image();im.src=e.directory+'/native.png';e.groups.forEach((g,i)=>select.add(new Option('▶ '+g.name,'loop:'+i)));e.meta.frames.forEach((f,i)=>select.add(new Option(f.name,'frame:'+i)));const view={e,select,canvas,label,im,last:-1};views.push(view);select.onchange=()=>{view.last=-1;draw(view,performance.now());};}
function draw(v,now){if(!v.im.complete||!atlas.complete)return;const [mode,n]=v.select.value.split(':'),group=v.e.groups[+n],i=mode==='loop'?group.frames[Math.floor(now/1000*group.fps)%group.frames.length]:+n;if(v.last===i)return;v.last=i;const f=v.e.meta.frames[i],h=Math.max(170,f.h+42),c=v.canvas;c.width=320*zoom;c.height=h*zoom;const t=c.getContext('2d');t.imageSmoothingEnabled=false;t.scale(zoom,zoom);t.fillStyle=night?'#29434e':'#edf1df';t.fillRect(0,0,320,h);t.fillStyle=night?'#55747f':'#a6bec5';t.fillRect(0,h-22,320,1);const anchor=f.anchor;t.drawImage(v.im,f.x,f.y,f.w,f.h,160-anchor[0],h-22-anchor[1],f.w,f.h);t.drawImage(atlas,512,0,22,24,45,h-46,22,24);v.label.textContent=f.name;}
function redraw(){views.forEach(v=>v.last=-1);views.forEach(v=>draw(v,performance.now()));}
document.querySelector('#native').onclick=()=>{zoom=1;document.querySelector('#native').setAttribute('aria-pressed','true');document.querySelector('#zoom').setAttribute('aria-pressed','false');redraw();};document.querySelector('#zoom').onclick=()=>{zoom=3;document.querySelector('#native').setAttribute('aria-pressed','false');document.querySelector('#zoom').setAttribute('aria-pressed','true');redraw();};document.querySelector('#play').onclick=()=>{playing=!playing;document.querySelector('#play').textContent=playing?'Pause cycles':'Play cycles';document.querySelector('#play').setAttribute('aria-pressed',String(playing));};document.querySelector('#snow').onclick=()=>{night=!night;document.querySelector('#snow').setAttribute('aria-pressed',String(night));redraw();};Promise.all([atlas.decode(),...views.map(v=>v.im.decode())]).then(redraw);function frame(t){if(playing&&!document.hidden)views.forEach(v=>draw(v,t));requestAnimationFrame(frame)}requestAnimationFrame(frame);
</script></html>'''.replace('__DATA__',json.dumps(entries))
(r/'creature-art-round2.html').write_text(html)
print('Built round-two gallery:',len(entries),'assets')
